from fastapi import FastAPI, Depends, HTTPException
from sqlalchemy.orm import Session
from app import models, database
from typing import List

engine = create_engine("sqlite:///./test.db")
models.Base.metadata.create_all(bind=engine)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

app = FastAPI()

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

@app.post("/action-proposals/", response_model=models.ActionProposal)
def create_action_proposal(proposal: models.ActionProposalCreate, db: Session = Depends(get_db)):
    db_proposal = models.ActionProposal(**proposal.dict())
    db.add(db_proposal)
    db.commit()
    db.refresh(db_proposal)
    return db_proposal

@app.get("/action-proposals/{proposal_id}", response_model=models.ActionProposal)
def read_action_proposal(proposal_id: int, db: Session = Depends(get_db)):
    db_proposal = db.query(models.ActionProposal).filter(models.ActionProposal.id == proposal_id).first()
    if db_proposal is None:
        raise HTTPException(status_code=404, detail="Action proposal not found")
    return db_proposal

@app.post("/simulation-models/", response_model=models.SimulationModel)
def create_simulation_model(model: models.SimulationModelCreate, db: Session = Depends(get_db)):
    db_model = models.SimulationModel(**model.dict())
    db.add(db_model)
    db.commit()
    db.refresh(db_model)
    return db_model

@app.post("/simulation-runs/", response_model=models.SimulationRun)
def create_simulation_run(run: models.SimulationRunCreate, db: Session = Depends(get_db)):
    db_run = models.SimulationRun(**run.dict())
    db.add(db_run)
    db.commit()
    db.refresh(db_run)
    
    # Simple synchronous simulation execution for Phase 1
    db_run.status = "running"
    db.commit()
    
    # Placeholder simulation logic
    result = {"status": "completed", "outcomes": {"risk": 0.2, "cost": 0.5}}
    confidence_score = 0.75
    
    db_run.status = "completed"
    db_run.result = result
    db_run.confidence_score = confidence_score
    db.commit()
    
    # Add sample metrics
    metrics = [
        models.OutcomeMetric(simulation_run_id=db_run.id, metric_name="risk_probability", value=0.2, weight=0.3, category="risk"),
        models.OutcomeMetric(simulation_run_id=db_run.id, metric_name="cost_impact", value=0.5, weight=0.2, category="cost"),
        models.OutcomeMetric(simulation_run_id=db_run.id, metric_name="time_to_complete", value=0.8, weight=0.1, category="speed")
    ]
    db.add_all(metrics)
    db.commit()
    
    return db_run.get(SimulationRun, db_run.id)


