import pytest
from fastapi.testclient import TestClient
from app.main import app, get_db
from app.database import engine, Base, SessionLocal
from app.models import ActionProposalCreate, SimulationRunCreate

client = TestClient(app)

@pytest.fixture
def db_session():
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        yield db
    finally:
        db.rollback()
        db.close()
        Base.metadata.drop_all(bind=engine)

def test_create_action_proposal(db_session):
    proposal_data = {
        "name": "Test Deployment",
        "description": "Test deployment to staging",
        "parameters": {"environment": "staging", "rollback": True},
        "domain": "devops",
        "target_environment": "staging",
        "expected_goals": ["successful deployment", "zero downtime"]
    }
    
    response = client.post("/action-proposals/", json=proposal_data)
    assert response.status_code == 201
    data = response.json()
    assert data["name"] == "Test Deployment"
    assert "id" in data
    assert "created_at" in data

def test_create_simulation_run(db_session):
    # First create an action proposal
    proposal_data = {
        "name": "Test Simulation",
        "description": "Test simulation for API",
        "parameters": {"test_param": "value"},
        "domain": "testing",
        "target_environment": "test",
        "expected_goals": ["test success"]
    }
    response = client.post("/action-proposals/", json=proposal_data)
    proposal_id = response.json()["id"]
    
    # Create a simulation model
    model_data = {
        "name": "Test Model",
        "description": "Test simulation model",
        "type": "rule_based",
        "config": {"test_config": "value"}
    }
    response = client.post("/simulation-models/", json=model_data)
    model_id = response.json()["id"]
    
    # Create simulation run
    run_data = {
        "action_proposal_id": proposal_id,
        "simulation_model_id": model_id,
        "status": "queued",
        "parameters": {"test_run": "value"},
        "result": None,
        "confidence_score": None
    }
    response = client.post("/simulation-runs/", json=run_data)
    assert response.status_code == 201
    data = response.json()
    assert data["status"] == "completed"
    assert data["confidence_score"] == 0.75
    assert "outcomes" in data["result"]


